import React, { useEffect, useRef, useState } from "react";
import { createChart, CrosshairMode } from "lightweight-charts";
import { EMA, RSI } from "technicalindicators";

/* ── Simulated candle generator (fallback when API has no data) ── */
function generateCandles(symbol, points = 140) {
  const seed = symbol.split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  const candles = [];
  let close = 800 + (seed % 600);
  const now = new Date();
  for (let i = points; i > 0; i--) {
    const d = new Date(now);
    d.setDate(d.getDate() - i);
    const ymd = d.toISOString().slice(0, 10);
    const r = Math.sin(seed + i) * 2 + (Math.random() - 0.5) * 3;
    const open = close;
    close = Math.max(1, open + r);
    candles.push({
      time: ymd,
      open,
      high: Math.max(open, close) + Math.random() * 3,
      low: Math.min(open, close) - Math.random() * 3,
      close,
      value: Math.round(600 + Math.random() * 1200),
    });
  }
  return candles;
}

/* ── Render indicators on the chart ── */
function drawIndicators(chart, seriesMap, data) {
  // Remove old indicator series
  Object.keys(seriesMap.current).forEach((k) => {
    if (k !== "candles" && k !== "volume" && seriesMap.current[k]) {
      try { chart.removeSeries(seriesMap.current[k]); } catch (_) {}
      delete seriesMap.current[k];
    }
  });

  const closes = data.map((d) => d.close);
  const map = (vals) => {
    const off = data.length - vals.length;
    return vals.reduce((r, v, i) => {
      if (v != null && !isNaN(v)) r.push({ time: data[i + off].time, value: v });
      return r;
    }, []);
  };

  // EMA 20
  const emaVals = EMA.calculate({ period: 20, values: closes });
  const ema = chart.addLineSeries({ color: "#ff9800", lineWidth: 2, title: "EMA (20)" });
  ema.setData(map(emaVals));
  seriesMap.current.ema = ema;

  // RSI 14
  const rsiVals = RSI.calculate({ period: 14, values: closes });
  const rsi = chart.addLineSeries({ color: "#9c27b0", lineWidth: 2, title: "RSI (14)", priceScaleId: "rsi" });
  chart.priceScale("rsi").applyOptions({ scaleMargins: { top: 0.8, bottom: 0 } });
  rsi.setData(map(rsiVals));
  seriesMap.current.rsi = rsi;
}

/* ── Main Component ── */
export default function TradingChart({ symbol, timeframe }) {
  const containerRef = useRef(null);
  const chartRef = useRef(null);
  const seriesMap = useRef({});
  const dataRef = useRef([]);
  const [loading, setLoading] = useState(true);
  const [source, setSource] = useState(""); // "live" or "simulated"

  // 1. Create chart once
  useEffect(() => {
    if (!containerRef.current) return;
    const chart = createChart(containerRef.current, {
      layout: { background: { color: "#131722" }, textColor: "#d1d4dc", fontSize: 12 },
      grid: { vertLines: { color: "#2a2e39" }, horzLines: { color: "#2a2e39" } },
      crosshair: { mode: CrosshairMode.Normal },
      rightPriceScale: { borderColor: "#2a2e39", autoScale: true, scaleMargins: { top: 0.1, bottom: 0.25 } },
      timeScale: { borderColor: "#2a2e39", timeVisible: true, secondsVisible: false },
    });
    seriesMap.current.candles = chart.addCandlestickSeries({
      upColor: "#26a69a", downColor: "#ef5350", borderVisible: false,
      wickUpColor: "#26a69a", wickDownColor: "#ef5350",
    });
    seriesMap.current.volume = chart.addHistogramSeries({
      color: "rgba(38,166,154,0.5)", priceFormat: { type: "volume" },
      priceScaleId: "", scaleMargins: { top: 0.8, bottom: 0 },
    });
    chartRef.current = chart;

    const ro = new ResizeObserver(() => {
      if (containerRef.current)
        chart.applyOptions({ width: containerRef.current.clientWidth, height: containerRef.current.clientHeight });
    });
    ro.observe(containerRef.current);
    return () => { ro.disconnect(); chart.remove(); };
  }, []);

  // 2. Fetch data – try API first, fallback to simulated
  useEffect(() => {
    if (!chartRef.current || !seriesMap.current.candles || !symbol) return;
    let cancelled = false;

    (async () => {
      setLoading(true);
      let chartData = null;
      let dataSource = "simulated";

      try {
        const res = await fetch(`/api/stocks/${symbol}/history`);
        if (res.ok) {
          const json = await res.json();
          if (json.history && json.history.length > 0) {
            chartData = json.history
              .map((r) => ({
                time: r.date,
                open: +r.open, high: +r.high, low: +r.low, close: +r.close,
                value: +r.volume,
              }))
              .sort((a, b) => (a.time > b.time ? 1 : -1));
            dataSource = "live";
          }
        }
      } catch (_) { /* fall through to simulated */ }

      if (!chartData) chartData = generateCandles(symbol);
      if (cancelled) return;

      dataRef.current = chartData;
      setSource(dataSource);

      const { candles, volume } = seriesMap.current;
      const chart = chartRef.current;
      candles.setData(chartData);
      volume.setData(
        chartData.map((d) => ({
          time: d.time, value: d.value,
          color: d.close > d.open ? "rgba(38,166,154,0.5)" : "rgba(239,83,80,0.5)",
        }))
      );
      drawIndicators(chart, seriesMap, chartData);
      chart.timeScale().fitContent();
      setLoading(false);
    })();

    return () => { cancelled = true; };
  }, [symbol, timeframe]);

  // 3. Simulate live tick every 2.5s
  useEffect(() => {
    if (!seriesMap.current.candles) return;
    const timer = setInterval(() => {
      const d = dataRef.current;
      const last = d[d.length - 1];
      if (!last) return;
      const change = (Math.random() - 0.5) * 4;
      const open = last.close;
      const close = Math.max(1, open + change);
      const today = new Date().toISOString().slice(0, 10);
      const tick = {
        time: today, open, close,
        high: Math.max(open, close) + Math.random() * 2,
        low: Math.min(open, close) - Math.random() * 2,
        value: Math.round(600 + Math.random() * 1200),
      };
      seriesMap.current.candles.update(tick);
      seriesMap.current.volume.update({
        time: today, value: tick.value,
        color: close >= open ? "rgba(38,166,154,0.5)" : "rgba(239,83,80,0.5)",
      });
    }, 2500);
    return () => clearInterval(timer);
  }, [symbol, timeframe]);

  return (
    <div className="trading-chart-container" style={{ width: "100%", height: "100%", position: "relative" }}>
      {loading && (
        <div style={{ position: "absolute", inset: 0, zIndex: 10, display: "grid", placeItems: "center", background: "rgba(19,23,34,0.8)", color: "#d1d4dc" }}>
          Loading Chart…
        </div>
      )}
      {source === "simulated" && !loading && (
        <div style={{ position: "absolute", top: 6, left: 8, zIndex: 5, fontSize: 11, color: "#f59e0b", background: "rgba(19,23,34,0.7)", padding: "2px 8px", borderRadius: 4 }}>
          Simulated Data
        </div>
      )}
      <div ref={containerRef} style={{ width: "100%", height: "100%" }} />
    </div>
  );
}
